/*
 * Bitcoin core: seeds, derivation paths, xpubs, addresses, SeedQR, dice and
 * BIP-85. A C port of what SeedSigner gets from its Seed model, embit_utils,
 * mnemonic_generation and the SeedQR encoders, on top of libwally-core.
 *
 * Every function is checked against vectors generated by running
 * SeedSigner's own code (sim/vectors/seedsigner_core.h, sim/test_btc.c).
 *
 * Secrets: seed_t holds the mnemonic, passphrase and BIP-39 seed. Keep it in
 * internal RAM (static or MALLOC_CAP_INTERNAL), and call seed_clear() when
 * done. Temporaries inside this module are wiped before returning.
 */
#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* libwally is built without Elements, which changes the size of its public
 * PSBT and transaction structs. Code that includes its headers without the
 * same definition reads those structs at the wrong offsets. */
#ifndef WALLY_ABI_NO_ELEMENTS
#  error "Build with WALLY_ABI_NO_ELEMENTS=1, as components/libwally-core is"
#endif

typedef enum { BTC_NET_MAIN, BTC_NET_TEST, BTC_NET_REGTEST } btc_net_t;
typedef enum { BTC_SIG_SINGLE, BTC_SIG_MULTI, BTC_SIG_INVALID } btc_sig_t;
typedef enum {
    BTC_SCRIPT_P2PKH,           /* SeedSigner "leg": legacy */
    BTC_SCRIPT_P2SH_P2WPKH,     /* "nes": nested segwit */
    BTC_SCRIPT_P2WPKH,          /* "nat": native segwit */
    BTC_SCRIPT_P2TR,            /* "tr": taproot, BIP-86 key path */
    BTC_SCRIPT_INVALID,
} btc_script_t;

/* ---- BIP-39 wordlist ---------------------------------------------------- */

#define BIP39_WORDS 2048
extern const char *const BIP39_WORDLIST[BIP39_WORDS];
/* Index of `word`, or -1. */
int bip39_word_index(const char *word);

/* ---- Seeds -------------------------------------------------------------- */

#define SEED_MAX_WORDS 24
#define SEED_PASSPHRASE_MAX 100

typedef struct {
    uint16_t words[SEED_MAX_WORDS];
    uint8_t n_words;                        /* 12 or 24 */
    char passphrase[SEED_PASSPHRASE_MAX + 1];
    uint8_t bytes[64];                      /* BIP-39 seed */
    uint8_t fingerprint[4];
} seed_t;

typedef enum {
    SEED_OK = 0,
    SEED_ERR_WORD_COUNT,    /* not 12 or 24 words */
    SEED_ERR_UNKNOWN_WORD,
    SEED_ERR_CHECKSUM,
    SEED_ERR_PASSPHRASE,    /* longer than the limit, or not printable ASCII */
    SEED_ERR_INTERNAL,
} seed_err_t;

/* From word indexes. The checksum must be valid. */
seed_err_t seed_from_indices(seed_t *s, const uint16_t *idx, size_t n,
                             const char *passphrase);
/* From words separated by spaces. */
seed_err_t seed_from_mnemonic(seed_t *s, const char *mnemonic,
                              const char *passphrase);
/* Change the passphrase; recomputes the seed and fingerprint. The device
 * types passphrases on a character wheel of printable ASCII, for which
 * BIP-39's NFKD normalisation changes nothing. */
seed_err_t seed_set_passphrase(seed_t *s, const char *passphrase);
void seed_clear(seed_t *s);
void seed_fingerprint_hex(const seed_t *s, char out[9]);
/* The words, space separated. Returns the length, or 0 if `cap` is short. */
size_t seed_mnemonic(const seed_t *s, char *out, size_t cap);
/* The BIP-39 entropy (16 or 32 bytes); returns its length. */
size_t seed_entropy(const seed_t *s, uint8_t out[32]);

/* ---- Derivation and keys ----------------------------------------------- */

/* SeedSigner's get_standard_derivation_path. False where SeedSigner raises
 * (taproot multisig, invalid arguments). */
bool btc_standard_path(btc_net_t net, btc_sig_t sig, btc_script_t script,
                       char *out, size_t cap);

/* embit's detect_version for a public key: zpub for 84', ypub for 49',
 * Zpub/Ypub for 48'/../2' and ../1', otherwise xpub; testnet and regtest
 * get their t/u/v/U/V forms. 0 for an unparseable path. */
uint32_t btc_slip132_version(const char *path, btc_net_t net);

/* The xpub at `path` (e.g. "m/84'/0'/0'"). `version` 0 means the generic
 * xpub/tpub. */
bool btc_xpub(const uint8_t *seed, size_t seed_len, const char *path,
              btc_net_t net, uint32_t version, char *out, size_t cap);

/* SeedSigner's static xpub export: "[fingerprint/path]xpub", with the
 * SLIP-132 version btc_slip132_version picks. */
bool btc_xpub_export(const seed_t *s, const char *path, btc_net_t net,
                     char *out, size_t cap);

/* SeedSigner's get_single_sig_address: the address at <change>/<index>
 * below an account xpub, in any SLIP-132 version. */
bool btc_address(const char *xpub, btc_script_t script, uint32_t index,
                 bool change, btc_net_t net, char *out, size_t cap);

/* ---- SeedQR ------------------------------------------------------------- */

/* Standard SeedQR: four decimal digits per word. `out` needs 4 * words + 1. */
bool seedqr_encode_standard(const seed_t *s, char *out, size_t cap);
/* Compact SeedQR: the entropy bytes. Returns the length (16 or 32). */
size_t seedqr_encode_compact(const seed_t *s, uint8_t out[32]);
/* Decoding gives word indexes; the checksum is checked by seed_from_indices.
 * Returns the word count, 0 if the payload is not a SeedQR. */
size_t seedqr_decode_standard(const char *digits, uint16_t idx[SEED_MAX_WORDS]);
size_t seedqr_decode_compact(const uint8_t *bytes, size_t len,
                             uint16_t idx[SEED_MAX_WORDS]);

/* ---- New seeds ---------------------------------------------------------- */

/* SeedSigner's generate_mnemonic_from_dice: SHA-256 of the roll string;
 * 50 rolls give 12 words, any other count 24. */
bool mnemonic_from_dice(const char *rolls, uint16_t idx[SEED_MAX_WORDS], size_t *n);
/* generate_mnemonic_from_coin_flips: 128 flips 12 words, otherwise 24. */
bool mnemonic_from_coin_flips(const char *flips, uint16_t idx[SEED_MAX_WORDS], size_t *n);
/* calculate_checksum: 11 or 23 words get a temporary final word ("abandon"),
 * then the last word is replaced by the one with a valid checksum. */
bool mnemonic_complete_checksum(const uint16_t *idx, size_t n,
                                uint16_t out[SEED_MAX_WORDS], size_t *out_n);
/* get_partial_final_word: 7 or 3 flips padded with zeros to a word index. */
int mnemonic_partial_final_word(const char *flips);
/* Word indexes from entropy (16 or 32 bytes), checksum included. */
bool mnemonic_from_entropy(const uint8_t *entropy, size_t len,
                           uint16_t idx[SEED_MAX_WORDS], size_t *n);

/* ---- BIP-85 ------------------------------------------------------------- */

/* The `index`th BIP-85 child mnemonic of `words` (12 or 24) words. */
bool bip85_child(const seed_t *s, uint32_t index, size_t words,
                 uint16_t idx[SEED_MAX_WORDS], size_t *n);
